  "shareLinks.revokeText": "Whoever has this link will no longer be able to open the page. This cannot be undone, but you can make a new link.",
  "shareLinks.revoked": "The link “{label}” no longer works.",
  "shareLinks.none": "No progress links yet.",
  "shareLinks.listLabel": "Progress links",
  "shareLinks.tooMany": "This project already has 20 progress links. Revoke one you no longer need, then make the new one.",
  "publicProgress.pageTitle": "{project}: progress",
  "publicProgress.kicker": "Progress of the data collection",
  "publicProgress.print": "Print",
  "publicProgress.invalidTitle": "This progress link does not work",
  "publicProgress.invalid": "The project's coordinators may have withdrawn it, or the address was not copied in full. Ask them for a new link.",
